//   script (markup removed, nothing else changed). Generated 2026-11-21.
import type { LiturgyBlock } from '../types';

export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-mol-0001", "section": "service", "who": "rubric", "text": "Алексию, митр. Московскому и всея России, чудотворцу,"},
  {"id": "cu-mol-0002", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0003", "section": "service", "who": "reader", "text": "Яко апостолом сопрестольна,/ и врача предобра, и служителя благоприятна,/ к раце твоей честней притекающе, святителю Алексие Богомудре, чудотворче,/ сошедшеся, любовию в память твою светло празднуем,/ в песнех и пениих радующеся и Христа славяще,/ таковую благодать тебе даровавшаго исцелений// и граду твоему великое утверждение."},
  {"id": "cu-mol-0004", "section": "service", "who": "rubric", "text": "Ин тропарь, на обретение мощей,"},
  {"id": "cu-mol-0005", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "cu-mol-0006", "section": "service", "who": "reader", "text": "Яко сокровище пребогатое, многолетно в земли сокровенное,/ честныя мощи твоя обретошася чудоточащия,/ всеблаженне отче святителю Алексие:/ от нихже врачевство приемлюще, обогащаемся/ и Христа славословим, глаголюще:// слава прославляющему святыя Своя."},
  {"id": "cu-mol-0007", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0008", "section": "service", "who": "rubric", "text": "Амфилохию, еп. Владимира Волынского,"},
  {"id": "cu-mol-0009", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0010", "section": "service", "who": "reader", "text": "От мирскаго мятежа изшед,/ в пещерах Киевских Феодосия блаженнаго Богомудренно вселился еси./ святителю Христов, отче Амфилохие,/ и отсюду во епископа Богоспасаемей пастве Владимиро-Волынстей поставленный,/ в трудех, бдениих и пощениих свято подвизался еси./ И тако достиг добродетелей совершенства,/ паки в пещеры святыя возвратился еси,/ идеже и дух свой благочестно предал еси Господеви, всечестне,/ к лику преподобных Печерских причтен,/ с ними же молися Христу, всечестне,// спастися душам нашим."},
  {"id": "cu-mol-0011", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0012", "section": "service", "who": "rubric", "text": "Андрею, архиеп. Критскому,"},
  {"id": "cu-mol-0013", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0014", "section": "service", "who": "reader", "text": "Христову Церковь цевницею языка твоего,/ песнословя умильно, возвеселил еси,/ богословием же Препетыя Троицы/ славу всем сказал еси ясно,/ тем тя, яко тайноглагольника, поем,/ Андрее, пастырю Критский,/ и величаем память твою,// Христа славяще дивнаго во святых Своих."},
  {"id": "cu-mol-0015", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0016", "section": "service", "who": "rubric", "text": "Антонию Вологодскому,"},
  {"id": "cu-mol-0017", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0018", "section": "service", "who": "reader", "text": "Иже от юности, Богомудре, возследуя Христу,/ во бдениих и в пощениих пребывая,/ и паству от Бога дарованную ти добре пасый,/ и учений Божественных исполняя и в жизненный путь наставляя:/ отнюду же и архиерейства саном почтеся,/ Церковь и люди возвеселил еси;/ и по преставлении своем чудес лучи испущаеши,/ недугом с верою приходящим к тебе исцеление подая,/ и слепу младенцу свет дарова,/ угодниче Христов, святителю Антоние,/ предстоя Престолу Христову с лики Ангельскими,/ с ними же моли Его о нас, притекающих к тебе,// получити от Него оставление грехов и велию милость."},
  {"id": "cu-mol-0019", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0020", "section": "service", "who": "rubric", "text": "Арсению, архиеп. Сербскому,"},
  {"id": "cu-mol-0021", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0022", "section": "service", "who": "reader", "text": "Милости наставниче, и благоутробия сокровище,/ еже всем отверзл еси,/ правоверия учителю, и архиереев Божественное удобрение,/ отче наш иерарше Арсение,/ нищих был еси заступник:/ тем моли Христа Бога,// просветити души наша, да не когда уснем в смерть."},
  {"id": "cu-mol-0023", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0024", "section": "service", "who": "rubric", "text": "Арсению, еп. Тверскому,"},
  {"id": "cu-mol-0025", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0026", "section": "service", "who": "reader", "text": "Благочестно пожив во святительстве,/ люди просветил еси учением твоим,/ и о храме Пречистыя вельми подвизався,/ и любитель монахов быв,/ сего ради от Христа паствы твоея венец приял еси./ Темже, яко апостольскаго престола наместника,/ и святителя великаго чтуще тя, молим чада твоя, блаженне:/ от всех бед избави нас яже ко Христу молитвами твоими,// святителю Христов Арсение, отче наш."},
  {"id": "cu-mol-0027", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "cu-mol-0028", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0029", "section": "service", "who": "reader", "text": "Божественною свыше просветився благодатию, святителю,/ и многим терпением во временней жизни подвиг совершил еси./ Темже источаеши чудес благодать/ иже с верою приходящим к честней раце мощей твоих, Арсение преблаженне./ Мы же вопием ти:/ слава Давшему ти крепость,/ слава Венчавшему тя,// слава Действующему тобою всем исцеления."},
  {"id": "cu-mol-0030", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0031", "section": "service", "who": "rubric", "text": "Афанасию Великому, архиеп. Александрийскому,"},
  {"id": "cu-mol-0032", "section": "service", "who": "rubric", "text": "глас 3:"},
  {"id": "cu-mol-0033", "section": "service", "who": "reader", "text": "Столп был еси православия,/ Божественными догматы подтверждая Церковь,/ священноначальниче Афанасие:/ Отцу бо Сына Единосущна проповедав,/ посрамил еси Ария./ Отче преподобне,/ Христа Бога моли,// даровати нам велию милость."},
  {"id": "cu-mol-0034", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0035", "section": "service", "who": "rubric", "text": "Афанасию, патриарху Цареградскому,"},
  {"id": "cu-mol-0036", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0037", "section": "service", "who": "reader", "text": "Чистоты жития светом страстное терние попалил еси/ и течением слез безплодную землю напоил еси,/ многоплодну ниву душевную соделав,/ Афанасие треблаженне,/ светило Царюграду, Патриархом удобрение,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0038", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0039", "section": "service", "who": "rubric", "text": "Афанасию, патриарху Цареградскому, Лубенскому чудотворцу,"},
  {"id": "cu-mol-0040", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0041", "section": "service", "who": "reader", "text": "Премудростию учений твоих царствующий град просветив,/ тьму неведения еретического разгнал еси, преблаженне;/ твое благословение земли Российстей принесл еси,/ отче наш, святителю Афанасие,/ идеже скончав течение твое,/ на крилех чистоты возлетел еси в Небесное Царство.// Моли Христа Бога непрестанно о душах наших."},
  {"id": "cu-mol-0042", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0043", "section": "service", "who": "rubric", "text": "Варсонофию, еп. Тверскому,"},
  {"id": "cu-mol-0044", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0045", "section": "service", "who": "reader", "text": "Возвестителю пути спасительнаго,/ истинный хранителю апостольских преданий,/ столпе непоколебимый, благочестия учителю/ и Православия наставниче, святителю Варсонофие,/ Владыку всех моли/ мир вселенней даровати// и душам нашим велию милость."},
  {"id": "cu-mol-0046", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0047", "section": "service", "who": "rubric", "text": "Василию Великому, архиеп. Кесарии Каппадокийской,"},
  {"id": "cu-mol-0048", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0049", "section": "service", "who": "reader", "text": "Во всю землю изыде вещание твое,/ яко приемшую слово твое,/ имже боголепно научил еси,/ естество сущих уяснил еси,/ человеческия обычаи украсил еси,/ царское священие, отче преподобне,/ моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0050", "section": "service", "who": "rubric", "text": "Величание"},
  {"id": "cu-mol-0051", "section": "service", "who": "reader", "text": "Величаем тя,/ святителю Христов Василие,// благочестно Церковь Христову сохраншаго."},
  {"id": "cu-mol-0052", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0053", "section": "service", "who": "rubric", "text": "Василию, еп. Захолмскому (Серб.),"},
  {"id": "cu-mol-0054", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0055", "section": "service", "who": "reader", "text": "От юности твоея всего себе Господеви отдал еси,/ пребывая в молитвах, трудех и постех, отче Богоносне,/ образ был еси добродетели своему стаду;/ сего ради видя Бог твое благое произволение,/ поставляет тя Своей Церкви пастыря и добляго архиерея/ и по преставлении твоем соблюде святое тело твое нерушимо, святителю Василие./ Темже, яко имея дерзновение,/ молися Христу Богу// спастися душам нашим."},
  {"id": "cu-mol-0056", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0057", "section": "service", "who": "rubric", "text": "Василию, еп. Рязанскому,"},
  {"id": "cu-mol-0058", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0059", "section": "service", "who": "reader", "text": "Первее в Муроме святительством почтен был еси,/ из негоже неправедно изгоняемь,/ на мантию, яко на легкий корабль, возшел еси,/ на нейже паче естества, яко безплотен,/ по водам шествие творя,/ промышлением Вышняго и заступлением Богоматере управляемь,/ богоспасаемаго града Рязани достигл еси/ и в нем, архиерейства престол восприим,/ богоданную паству рязанскую добре упасл еси,/ святителю отче наш Василие,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0060", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0061", "section": "service", "who": "rubric", "text": "Геннадию, архиеп. Новгородскому,"},
  {"id": "cu-mol-0062", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0063", "section": "service", "who": "reader", "text": "Уподобился еси древним отцем,/ святителю отче Геннадие,/ Священныя Книги собрав и еретики посрамив,/ ревность по Бозе показуя, паству оградил еси,/ моли и ныне Христа Бога/ мир Церкви даровати// и спастися душам нашим."},
  {"id": "cu-mol-0064", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0065", "section": "service", "who": "rubric", "text": "Герасиму, еп. Великопермскому, Устьвымскому,"},
  {"id": "cu-mol-0066", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0067", "section": "service", "who": "reader", "text": "Божественныя веры проповеданием/ землю Зырянскую озарил еси/ и ко Христу люди многия привел еси./ Возопиет же с тобою и Авель ко Господу/ и Захариина кровь праведная,/ отче Герасиме, моли Христа Бога/ пастве твоей и всем, любовию память твою совершающим,// даровати велию милость."},
  {"id": "cu-mol-0068", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0069", "section": "service", "who": "rubric", "text": "Герасиму, Питириму и Ионе, епп. Великопермским, Устьвымским,"},
  {"id": "cu-mol-0070", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0071", "section": "service", "who": "reader", "text": "Равноапостольному святителю Стефану наследовавшии/ и Православия светом страну Зырянскую озарившии,/ святителие Христовы Герасиме, Питириме и Ионо,/ Престолу Пресвятыя Троицы ныне предстояще,/ молитеся пастве вашей от врагов ненаветованней быти// и всем православным людем в мире спастись."},
  {"id": "cu-mol-0072", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0073", "section": "service", "who": "rubric", "text": "Герману, архиеп. Казанскому,"},
  {"id": "cu-mol-0074", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0075", "section": "service", "who": "reader", "text": "От юности иго Христово усердно восприим,/ бденными подвиги поста и молитвы, прославился еси./ Отонудуже призывающу тя Богу на служение Церкви/ в новопросвещеннем царстве Казанстем,/ вкупе со святителем Гурием воззван был еси,/ идеже, яко первоначальник созданной тобою в граде Свияжске обители,/ и достойный первосвятителю преемник явился еси./ Духом предстоя Престолу Владычню,/ молися, святителю Германе, со святителем Гурием,/ православней пастве во благочестии преспевати,// и тьме иноверия светом веры разгнатися."},
  {"id": "cu-mol-0076", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0077", "section": "service", "who": "rubric", "text": "Геронтию, митр. Московскому и всея Руси,"},
  {"id": "cu-mol-0078", "section": "service", "who": "rubric", "text": "глас 6"},
  {"id": "cu-mol-0079", "section": "service", "who": "reader", "text": "Днесь душа всяка веселится/ на память успения святителя Христова Геронтия,/ премудрости ревнителя/ и кротости учителя,/ смирению наказателя,/ учением Божественных словес верныя насладившаго./ Русскаго митрополита похвалим,/ святительства паству приимшаго,/ украсившаго Церковь Христову./ Тем и Христос видя твое благопроизволение,/ причте тя в лик праведных,/ святителю Геронтие,/ моли Христа Бога и Пречистую Богородицу// непрестанно о всех нас."},
  {"id": "cu-mol-0080", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0081", "section": "service", "who": "rubric", "text": "Григорию Богослову, архиеп. Константинопольскому,"},
  {"id": "cu-mol-0082", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0083", "section": "service", "who": "reader", "text": "Пастырская свирель Богословия твоего/ риторов победи трубы,/ якоже бо глубины духа изыскавшу,/ и доброты вещания приложишася тебе./ Но моли Христа Бога, отче Григорие,// спастися душам нашим."},
  {"id": "cu-mol-0084", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0085", "section": "service", "who": "rubric", "text": "Григорию Двоеслову, папе Римскому,"},
  {"id": "cu-mol-0086", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0087", "section": "service", "who": "reader", "text": "Иже от Бога свыше Божественную благодать восприемь,/ славне Григорие,/ и Того силою укрепляемь,/ евангельски шествовати изволил еси./ Отонудуже у Христа возмездие трудов приял еси, всеблаженне,/ Егоже моли,// да спасет души наша."},
  {"id": "cu-mol-0088", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0089", "section": "service", "who": "rubric", "text": "Григорию Паламе, архиеп. Фессалонитскому,"},
  {"id": "cu-mol-0090", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0091", "section": "service", "who": "reader", "text": "Православию наставниче, святителем украшение,/ богословцем поборниче непобедимый, Григорие чудотворче,/ Солуню великая похвало, проповедниче благодати,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0092", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0093", "section": "service", "who": "rubric", "text": "Григорию Чудотворцу, еп. Неокесарийскому,"},
  {"id": "cu-mol-0094", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0095", "section": "service", "who": "reader", "text": "В молитвах бодрствуя, чудес деланьми претерпевая,/ тезоимение стяжал еси исправления,/ но молися Христу Богу, отче Григорие,/ просветити души наша,// да не когда уснем в смерть."},
  {"id": "cu-mol-0096", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0097", "section": "service", "who": "rubric", "text": "Гурию, архиеп. Казанскому,"},
  {"id": "cu-mol-0098", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0099", "section": "service", "who": "reader", "text": "Правило веры и образ целомудрия,/ учителя добрых дел/ и наставника спасения даде тя Господь/ новопросвещенному граду Казани,/ в немже приобрел еси новыя от язык люди/ и привел еси я Христови./ Сего ради в память твою радостно сошедшеся,/ честне празднуем святое твое успение,/ ты же, отче наш, святителю Христов Гурие,/ моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0100", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "cu-mol-0101", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0102", "section": "service", "who": "reader", "text": "Яко крин благовонный,/ мироточивыя твоя мощи/ от вертограда Церкве Спасовы/ в вертоград Церкве Богородичны честне принесошася,/ святителю Гурие,/ яко же бо дар честен,/ тя даровав Христос Пречистей Матери Своей,/ и исполнися храм Ея святый благоухания твоего,/ и возрадовася архиерейский престол,/ приемый тя, первоседателя своего./ Возвеселися же собор верных со святителем и священноначальники/ о преславном цельбоносных твоих мощей пренесении,/ еже мы радостно празднующе, молим тя, угодниче Божий:/ моли Христа Бога// подати душам нашим мир и велию милость."},
  {"id": "cu-mol-0103", "section": "service", "who": "rubric", "text": "Ин тропарь, на обретение мощей,"},
  {"id": "cu-mol-0104", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0105", "section": "service", "who": "reader", "text": "Первии учителие прежде темному,/ ныне же светлому и новопросвещенному граду Казани,/ первии возсветителие пути спасительнаго,/ истиннии хранителие апостольских преданий,/ столпи непоколебимии, благочестия учителие/ и Православия наставницы, Гурие и Варсонофие,/ Владыку всех молите// мир вселенней даровати и душам нашим велию милость."},
  {"id": "cu-mol-0106", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0107", "section": "service", "who": "rubric", "text": "Даниилу, архиеп. Сербскому,"},
  {"id": "cu-mol-0108", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0109", "section": "service", "who": "reader", "text": "Чудо явися извещения,/ делами добродетелей Божиих возсиял еси,/ монашествующих лики упасл еси,/ архиерейская седалища утвердил еси,/ еретическаго нападения не усумневся,/ Церковию Христовою управляя,/ преподобне отче, Данииле премудре,/ уснув, яко спя,/ тело же твое цело и нетленно соблюдено бысть,/ и подает цельбы болящим от различных недугов,/ и демоны прогоняет./ Сего ради молим тя:// моли спастися душам нашим."},
  {"id": "cu-mol-0110", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0111", "section": "service", "who": "rubric", "text": "Димитрию, митр. Ростовскому,"},
  {"id": "cu-mol-0112", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0113", "section": "service", "who": "reader", "text": "Православия ревнителю и раскола искоренителю,/ Российский целебниче, и новый к Богу молитвенниче,/ списаньми твоими буих уцеломудрил еси,/ цевнице духовная, Димитрие блаженне,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0114", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0115", "section": "service", "who": "rubric", "text": "Димитрию, митр. Ростовскому, Митрофану и Тихону, епп. Воронежским,"},
  {"id": "cu-mol-0116", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0117", "section": "service", "who": "reader", "text": "Якоже древле на Востоцех трие велицыи святителие,/ сильный словом Василий,/ глубина Богословия Григорий и Златоустый Иоанн,/ тако и днесь в стране полунощней/ три новоявленная светила веры на тверди церковней востекоша:/ столп веры Митрофан,/ слово истины в лице царю исповедавый,/ и обличитель раскола Димитрий,/ мечем обоюду острым вся козни его разсекий,/ и помазания полный сосуд Тихон,/ тихостию словес своих грешника к покаянию призвавый./ О велицыи трие святителие земли Российския,/ молите Христа Бога, Емуже угодни бысте,// спастися душам нашим."},
  {"id": "cu-mol-0118", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0119", "section": "service", "who": "rubric", "text": "Дионисию, архиеп. Суздальскому,"},
  {"id": "cu-mol-0120", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0121", "section": "service", "who": "reader", "text": "Православия ревнителю, благочестия наставниче,/ ищущим спасения добрый кормчий,/ монашествующих Богодухновенное украшение,/ Богоноснаго Евфимия собеседниче, святителю Дионисие,/ ученьми и добродетельми отечество твое просветил еси,/ не забуди нас, чтущих тя,// но в мире управи живот наш."},
  {"id": "cu-mol-0122", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0123", "section": "service", "who": "rubric", "text": "Донату, еп. Еврии,"},
  {"id": "cu-mol-0124", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0125", "section": "service", "who": "reader", "text": "Блажен делатель и украситель Церкве Христовы,/ отче Донате, был еси,/ непрестанно попечение о стаде твоем стяжав,/ научая и руководя оно в любви Сына Божия,/ не токмо бо в твоем граде многий народ,/ но в Константинополе самодержца и в нем вся люди/ удивил еси/ преславными чудесы твоими./ Богоугодныя убо мольбы/ сотворяя ко Христу Богу,/ помощник скор всем явися,/ предстоя Всесвятей Троице,/ в Вышних моли Ю о всех нас,// да спасет души наша."},
  {"id": "cu-mol-0126", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0127", "section": "service", "who": "rubric", "text": "Евстафию I, архиеп. Сербскому,"},
  {"id": "cu-mol-0128", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0129", "section": "service", "who": "reader", "text": "Избран от Бога, возлюблен от людей,/ архиереов Божественная красото,/ отче Евстафие, Ангелов сослужителю,/ таин же Божественных проповедатель был еси,/ темже моли Христа Бога со всеми святыми/ избавитися от всяких зол/ молитвами твоими, блаженне,/ и спастися нам,// чтущим любовию святую память твою."},
  {"id": "cu-mol-0130", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0131", "section": "service", "who": "rubric", "text": "Евфимию, патриарху Болгарскому,"},
  {"id": "cu-mol-0132", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0133", "section": "service", "who": "reader", "text": "Подвигом пустынным просиял еси/ и на престол первосвятительства по достоянию возшел еси,/ отонудуже лучами Боговедения и добродетели всех озарил еси/ и чашу мученичества безкровно отпил еси./ Ныне же предстоя престолу Горняго Иерусалима, Евфимие,/ моли седящаго на нем Христа Бога нашего// о почитающих честную память твою."},
  {"id": "cu-mol-0134", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0135", "section": "service", "who": "rubric", "text": "Евфимию, архиеп. Новгородскому, чудотворцу,"},
  {"id": "cu-mol-0136", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0137", "section": "service", "who": "reader", "text": "Избран быв Богови от юности,/ святителю Евфимие,/ и сего ради архиерейства саном почтен быв,/ упасл еси люди, иже тебе Богом врученныя;/ темже и по преставлении чудес дарования от Господа приял еси/ исцеляти различныя недуги./ Того моли о нас,/ совершающих честную память твою,// да тебе вси непрестанно ублажаем."},
  {"id": "cu-mol-0138", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0139", "section": "service", "who": "rubric", "text": "Ефрему, патриарху Сербскому,"},
  {"id": "cu-mol-0140", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0141", "section": "service", "who": "reader", "text": "Патриархов великое удобрение,/ святителем красото, монахом правило,/ пустынником славу, милости подателя,/ разсуждения светильника,/ сошедшеся, вернии, восхвалим,/ кротости учителя, Божественнаго рачителя,/ премудраго архипастыря, великаго святителя и отца,/ Ефрема, Патриарха Сербскаго,/ звезду, темныя люди просвещающую/ и вся верныя озаряющую./ Темже, притекающе к раце мощей его,/ любовию целуем я и вопием:/ святе святый, непрестай молити Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0142", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0143", "section": "service", "who": "rubric", "text": "Иакову, еп. Ростовскому,"},
  {"id": "cu-mol-0144", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0145", "section": "service", "who": "reader", "text": "Избран от юности Богови быв,/ святителю Иакове,/ сего ради архиерейства саном почтен,/ упасл еси люди, яже тебе Богом врученныя./ Темже и по преставлении/ чудес дарования от Бога приял еси/ исцеляти различныя недуги./ Моли о нас, совершающих честную память твою,// да тебе непрестанно величаем."},
  {"id": "cu-mol-0146", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0147", "section": "service", "who": "rubric", "text": "Игнатию Брянчанинову, еп. Кавказскому и Черноморскому,"},
  {"id": "cu-mol-0148", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0149", "section": "service", "who": "reader", "text": "Православия поборниче,/ покаяния и молитвы делателю и учителю изрядный,/ архиереев богодухновенное украшение,/ монашествующих славо и похвало:/ писании твоими вся ны уцеломудрил еси./ Цевнице духовная, Игнатие богомудре,/ моли Слова Христа Бога,/ Егоже носил еси в сердце твоем,// даровати нам прежде конца покаяние."},
  {"id": "cu-mol-0150", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0151", "section": "service", "who": "rubric", "text": "Игнатию, еп. Ростовскому,"},
  {"id": "cu-mol-0152", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0153", "section": "service", "who": "reader", "text": "Благоверия просвещся учении,/ святительства прием паству/ и апостолов наследник быв,/ тем приял еси от Бога дар чудес, святителю отче Игнатие,/ моли Христа Бога,// да спасет души наша."},
  {"id": "cu-mol-0154", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0155", "section": "service", "who": "rubric", "text": "Илариону, еп. Меглинскому,"},
  {"id": "cu-mol-0156", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0157", "section": "service", "who": "reader", "text": "Чудо явився извещения,/ делы возсиял еси добродетелей Божиих,/ монашествующих лики упасл еси,/ архиерейская седалища изчистил еси,/ еретическаго же нападания не усумневся,/ церкви Христовы воздвигл еси,/ преподобне Иларионе,/ умер, яко спя,/ тело же твое цело и нетленно соблюдено бысть,/ и подает цельбы болящим от различных недуг,/ и демоны прогоняет,/ сего ради молим тя:// моли спастися душам нашим."},
  {"id": "cu-mol-0158", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0159", "section": "service", "who": "rubric", "text": "Илариону, митр. Суздальскому,"},
  {"id": "cu-mol-0160", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0161", "section": "service", "who": "reader", "text": "Воспойте убо, вси людие,/ в Триех Ипостасех Единаго Бога,/ на Небесех непостижно пребывающаго,/ мановением же всяческая управляющаго,/ на землю же щедротно призирающаго,/ в пустынном же пребывающаго противу невидимых врагов,/ угодника Своего преподобнаго Илариона укрепльшаго,// того молитвами, Боже, помилуй и спаси нас."},
  {"id": "cu-mol-0162", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0163", "section": "service", "who": "rubric", "text": "Иннокентию, еп. Иркутскому,"},
  {"id": "cu-mol-0164", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0165", "section": "service", "who": "reader", "text": "Светильниче Церкве пресветлый,/ озаривый лучами доброт твоих страну сию,/ и исцеленьми многими притекающих к тебе с верою/ Бога прославивый,/ молим тя, святителю отче Иннокентие,/ ограждай молитвами твоими град сей// от всех бед и печали."},
  {"id": "cu-mol-0166", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0167", "section": "service", "who": "rubric", "text": "Иннокентию, митр. Московскому,"},
  {"id": "cu-mol-0168", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0169", "section": "service", "who": "reader", "text": "Во вся страны полунощныя изыде вещание твое,/ яко приемшия слово твое,/ ихже боголепно научил еси,/ неведущия Христа светом Евангелия просветил еси,/ человеческия обычаи украсил еси,/ Российская похвало, святителю отче наш Иннокентие,/ моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0170", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0171", "section": "service", "who": "rubric", "text": "Иннокентию, архиеп. Херсонскому,"},
  {"id": "cu-mol-0172", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0173", "section": "service", "who": "reader", "text": "От юных лет прилежа учению благочестия и страху Божию,/ во благодати Христовой преуспевая,/ стяжал еси словесная дарования/ и явился еси неутомимый проповедниче спасения,/ души верных озаряя спасительными смыслы/ и приводя всех ко исправлению./ Святителю отче Иннокентие,/ моли Христа Бога/ дати нам оставление грехов и велию милость."},
  {"id": "cu-mol-0174", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0175", "section": "service", "who": "rubric", "text": "Иоанну Златоусту, архиеп. Константинопольскому,"},
  {"id": "cu-mol-0176", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0177", "section": "service", "who": "reader", "text": "Уст твоих якоже светлость огня возсиявши благодать,/ вселенную просвети:/ не сребролюбия мирови сокровища сниска,/ высоту нам смиренномудрия показа./ Но твоими словесы наказуя, отче Иоанне Златоусте,// моли Слова Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0178", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0179", "section": "service", "who": "rubric", "text": "Иоанну Милостивому, патриарху Александрийскому,"},
  {"id": "cu-mol-0180", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0181", "section": "service", "who": "reader", "text": "В терпении твоем стяжал еси мзду твою, отче преподобне,/ в молитвах непрестанно терпевый,/ нищия возлюбивый и сия удовливый,/ но молися Христу Богу, Иоанне милостиве, блаженне,// спастися душам нашим."},
  {"id": "cu-mol-0182", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0183", "section": "service", "who": "rubric", "text": "Иоанну, архиеп. Новгородскому,"},
  {"id": "cu-mol-0184", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0185", "section": "service", "who": "reader", "text": "Днесь светло красуется славнейший Великий Новград,/ имея мощи твоя в себе, святителю Иоанне,/ яко солнечныя лучи испущающия/ и подающия исцеления притекающим к раце мощей твоих./ Молися Христу Богу избавити град сей невредимь от варварскаго пленения,/ и междоусобныя брани, и огненнаго запаления,/ святителю богомудре и чудоносче,/ Небесный человече и земный Ангеле:/ да сошедшеся любовию в память твою,/ светло празднуем, в песнех и пениих радующеся/ и Христа славяще, тебе таковую благодать даровавшаго исцелений// и Великому Новуграду заступление и утверждение."},
  {"id": "cu-mol-0186", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0187", "section": "service", "who": "rubric", "text": "Иоанну, еп. Суздальскому,"},
  {"id": "cu-mol-0188", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0189", "section": "service", "who": "reader", "text": "Управляя Церковь Божию Соборную и Апостольскую,/ соблюдая заповеди Божия,/ вельми добре упас стадо словесных овец;/ зломысленным церковником молитвою своею прозрети повеле,/ и научи, якоже прежде святый Леонтий,/ поспешник спасению Русския земли, учитель Ростовский,/ прежде связа и паки благослови;/ тако святый епископ Суждальский,/ напастем, притекающим к тебе, избавниче, чудотворче Иоанне,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0190", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0191", "section": "service", "who": "rubric", "text": "Иоанну, митр. Тобольскому,"},
  {"id": "cu-mol-0192", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0193", "section": "service", "who": "reader", "text": "Наставниче благочестия,/ сиротствующих питателю,/ скорбящих утешителю, недугующих врачу безмездный,/ душею страждущих скорый помощниче,/ теплый молитвенниче о всех ко Господу,/ святителю отче Иоанне,// моли Христа Бога, спастися душам нашим."},
  {"id": "cu-mol-0194", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0195", "section": "service", "who": "rubric", "text": "Иоанну и Феодору, епп. Суздальским,"},
  {"id": "cu-mol-0196", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0197", "section": "service", "who": "reader", "text": "Яко апостолом единонравных учителей Суждальския страны,/ и целителей душ и телес премудрых,/ и служителей Богу благоприятных,/ к ракам честных мощей ваших притекающе,/ ублажаем вас, святителие Богоблаженнии, Феодоре и Иоанне,/ в песнех же и пениих, радующеся, славим Христа,/ даровавшаго вам благодать исцелений// и граду нашему Суждалю великое в вас утверждение."},
  {"id": "cu-mol-0198", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0199", "section": "service", "who": "rubric", "text": "Иоанну (Максимовичу), архиеп. Шанхайскому и Сан-Францисскому,"},
  {"id": "cu-mol-0200", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0201", "section": "service", "who": "reader", "text": "Попечение твое о пастве в странствии ея,/ се прообраз и молитв твоих, за мир весь присно возносимых./ Тако веруем, познавше любовь твою,/ святителю и чудотворче Иоанне!/ Весь от Бога освящен священнодействием пречистых Таин,/ имиже сам присно укрепляем, поспешал еси ко страждущим, целителю отраднейший.// Поспеши и ныне в помощь нам всем сердцем чтущим тя."},
  {"id": "cu-mol-0202", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0203", "section": "service", "who": "rubric", "text": "Иоасафу, еп. Белгородскому,"},
  {"id": "cu-mol-0204", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0205", "section": "service", "who": "reader", "text": "Святителю Христу Богу возлюбленне,/ правило веры и образ милосердия людем был еси,/ бдением же, постом и молитвою/ яко светильник пресветлый просиял еси,/ и прославлен от Бога явился еси:/ телом убо в нетлении почивая,/ духом же Престолу Божию предстоя,/ чудеса преславная источаеши./ Моли Христа Бога,/ да утвердит нас в Православии и благочестии,// и спасет души наша."},
  {"id": "cu-mol-0206", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0207", "section": "service", "who": "rubric", "text": "Иову, патриарху Московскому и всея Руси,"},
  {"id": "cu-mol-0208", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0209", "section": "service", "who": "reader", "text": "Да торжествует Церковь Христова/ и да радуется град Москва/ яко возсия светильник земли Российския/ во исповедании Истины непоколебимый Иов Патриарх,/ егоже молитвами, Господи,/ вся соблазны мира сего и ереси искорени,/ люди во благочестии настави// и утверди в Православии."},
  {"id": "cu-mol-0210", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0211", "section": "service", "who": "rubric", "text": "Ионе, еп. Великопермскому,"},
  {"id": "cu-mol-0212", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0213", "section": "service", "who": "reader", "text": "Просветителю Вятския земли,/ строителю храмов Божиих,/ ревнителю благолепия церковнаго,/ подражателю преподобнаго Трифона,/ святителю отче Ионо,/ не остави чад твоих, в скорбех сущих,/ но огради нас молитвами твоими ко Господу,/ да спасет души наша."},
  {"id": "cu-mol-0214", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0215", "section": "service", "who": "rubric", "text": "Ионе, митр. Московскому и всея России, чудотворцу,"},
  {"id": "cu-mol-0216", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0217", "section": "service", "who": "reader", "text": "Ярем Господень измлада восприим,/ и Того стопам невозвратным желанием последовал еси,/ и освященнаго подвига достиже,/ святительства паству приим и чудес от Бога дары прият,/ с верою приходящим к раце мощей твоих/ подаеши различным недугом исцеление неоскудно,/ отче наш Ионо, святителю Христов,// моли Христа Бога даровати нам велию милость."},
  {"id": "cu-mol-0218", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "cu-mol-0219", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0220", "section": "service", "who": "reader", "text": "От юности твоея весь сам себе Господеви возложив,/ в молитвах и трудех, и в постех, образ быв добродетели,/ отонудуже видев Бог твое благое произволение,/ архиерея тя и пастыря Церкви Своей устрояет./ Темже и по преставлении, честное тело твое цело и нетленно соблюдеся,/ Ионо святителю:/ моли Христа Бога,// да спасет души наша."},
  {"id": "cu-mol-0221", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0222", "section": "service", "who": "rubric", "text": "Ионе, архиеп. Новгородскому,"},
  {"id": "cu-mol-0223", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0224", "section": "service", "who": "reader", "text": "Исправление веры, и образ кротости,/ и якоже сад посреде рая,/ преподобными делы твоими мир просвещаеши,/ и сего ради к мощем твоим любовию прикасаемся и верно вопием:/ предстани в помощь воспевающим память твою светоносную, отче Ионо,// и моли спастися душам нашим."},
  {"id": "cu-mol-0225", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0226", "section": "service", "who": "rubric", "text": "Исаии, еп. Ростовскому, чудотворцу,"},
  {"id": "cu-mol-0227", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "cu-mol-0228", "section": "service", "who": "reader", "text": "В иноцех святыя Лавры Печерския/ благоискусен показавыйся/ и во архиерейстем сане добр пастырь/ своему стаду, Боголюбезне Исаие, бывый,/ моли о нас Пастыреначальника Христа Бога// да помилует и спасет души наша."},
  {"id": "cu-mol-0229", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0230", "section": "service", "who": "rubric", "text": "Иувеналию, патриарху Иерусалимскому,"},
  {"id": "cu-mol-0231", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0232", "section": "service", "who": "reader", "text": "Брата Божия на престоле архиерейства преемниче,/ святаго града Иерусалима иерарше достохвальне,/ с богомудрыми отцы в Халкидоне изъяснил еси воплощение Сына Божия,/ пришедшаго мир обновити и обожити вся человеки,/ в Церкви Его с Ним сочетавшияся,/ святителю отче Иувеналие,/ предстоя ныне во Царствии Отца светов,/ о почитающих тя любовию молися,// да мир и милость Спасова будет с нам."},
  {"id": "cu-mol-0233", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0234", "section": "service", "who": "rubric", "text": "Киприану, митр. Московскому, всея России чудотворцу,"},
  {"id": "cu-mol-0235", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0236", "section": "service", "who": "reader", "text": "Иже от Бога свыше Божественною благодатию совершен/ и благими нравы украшен,/ Духом Святым просвещен,/ совершив святыню в страсе Божии,/ сподоблен бысть благодати Божественнаго Духа,/ пасый Церковь Божию Русския митрополии,/ постом вся поборая, волнение претерпе, гонение преминув,/ святаго Петра митрополита всегда себе в помощь призывая,/ и сего помощника имея,/ и того стопам последуя./ Служитель благоприятный,/ заповеди Божия соблюдая, Духом Божиим наставляемь,/ просвещая верныя люди учением словес твоих,/ пощением украси житие свое,/ ярем Господень измлада восприим,/ и паче всех Христа возлюби./ Того ради и архиерейским седалищем почтен,/ и, яко светозарное солнце, от Сербския земли происшед,/ и по вся концы Русский земли добродетелию просияв,/ светило явися мирови,/ и преставися ко Господу от сея жизни в вечный покой,/ великий архиерею Божий, Киприане митрополите,/ учителю и наставниче Русския земли,/ всегда предстоя Престолу Пресвятыя Троицы,/ моли Господа прилежно/ об архиереех и о всех христианех,// да спасет тебе ради души наша."},
  {"id": "cu-mol-0237", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0238", "section": "service", "who": "rubric", "text": "Киприану, Фотию и Ионе, митр. Московским и всея Руси, на перенесение мощей,"},
  {"id": "cu-mol-0239", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0240", "section": "service", "who": "reader", "text": "Яко Светлаго Солнца светозарныя звезды,/ Троическим Светом озаряете сердца верных,/ пренесением честных мощей ваших,/ Троицы сосуди явистеся чистии вашим житием,/ и научисте люди твердо вере Христове,/ и скверну отгнасте вашими святыми заповедьми,/ и упасосте добре Христово стадо, порученное вам,/ Богомудре Киприане, со славным Фотием и со Ионою твердым,// молитеся Христу Богу, да спасет души наша."},
  {"id": "cu-mol-0241", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0242", "section": "service", "who": "rubric", "text": "Кириллу, архиеп. Александрийскому,"},
  {"id": "cu-mol-0243", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0244", "section": "service", "who": "reader", "text": "Православия наставниче,/ благочестия учителю и чистоты,/ вселенныя светильниче,/ архиереев Богодухновенное удобрение,/ Кирилле премудре,/ ученьми твоими вся просветил еси,/ цевнице духовная,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0245", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0246", "section": "service", "who": "rubric", "text": "Кириллу, еп. Туровскому,"},
  {"id": "cu-mol-0247", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0248", "section": "service", "who": "reader", "text": "Благочестия ревнителю и рачителю,/ иноков и столпников похвало,/ святителю Туровския паствы, преславне,/ златословесный учителю,/ светлым учением Богоразумия своего просветивый концы русския,/ в молитве к Богу благодатный грешников споспешниче,/ Кирилле Богомудре, моли Христа Бога/ утвердитися нам, соотечественником твоим,// во Православии, благочестии и единомыслии."},
  {"id": "cu-mol-0249", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0250", "section": "service", "who": "rubric", "text": "Константину, митр. Киевскому и всея России, блж.,"},
  {"id": "cu-mol-0251", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0252", "section": "service", "who": "reader", "text": "Апостолов преемниче,/ архиереев сопрестольниче,/ России всея пастырю и учителю,/ всеблаженне отче Константине,/ Владыце всех молися/ мир пастве твоей даровати// и спасение душам нашим и велию милость."},
  {"id": "cu-mol-0253", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0254", "section": "service", "who": "rubric", "text": "Леонтию, еп. Ростовскому,"},
  {"id": "cu-mol-0255", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0256", "section": "service", "who": "reader", "text": "Апостолом сопричастник/ и к Богу молебник верен,/ добродетельми возшед на Небесная,/ и любовь возложил еси к Любящему тя,/ и неверныя люди обратил еси в веру./ Тем ныне со Ангелы ликуя,/ предстоиши Престолу славы всех Царя Христа Бога:/ молися, святителю Леонтие,// да спасет души наша."},
  {"id": "cu-mol-0257", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0258", "section": "service", "who": "rubric", "text": "Луке (Войно-Ясенецкому), архиеп. Крымскому, исп.,"},
  {"id": "cu-mol-0259", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0260", "section": "service", "who": "reader", "text": "Возвестителю пути спасительнаго,/ исповедниче непоколебимый,/ истинный хранителю отеческих преданий,/ Православия наставниче,/ Крымския земли архипастырю,/ врачу богомудрый, святителю Луко,/ Христа Спаса непрестанно моли,// даровати душам нашим велию милость."},
  {"id": "cu-mol-0261", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0262", "section": "service", "who": "rubric", "text": "Льву, папе Римскому,"},
  {"id": "cu-mol-0263", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0264", "section": "service", "who": "reader", "text": "Православия наставниче,/ благочестия учителю и чистоты,/ вселенныя светильниче, архиереев Богодухновенное удобрение,/ Льве премудре,/ ученьми твоими вся просветил еси, цевнице духовная.// Моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0265", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0266", "section": "service", "who": "rubric", "text": "Макарию, митр. Московскому,"},
  {"id": "cu-mol-0267", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0268", "section": "service", "who": "reader", "text": "Яко великим пастырем единонравна/ и учителем вселенныя единомысленна,/ Божия Премудрости служителя изрядна,/ иже блаженству тезоимениту,/ днесь, вернии, вси воспоим:/ Христа Бога моли, святителю Макарие,// умирити мир и спасти души наша."},
  {"id": "cu-mol-0269", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0270", "section": "service", "who": "rubric", "text": "Максиму Новому, бывшему деспоту Сербскому,"},
  {"id": "cu-mol-0271", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0272", "section": "service", "who": "reader", "text": "Странное рождение и воспитание был еси отче,/ но паки водворися во власти у своего народа,/ Небеснаго Царствия желая,/ земное царствие оставил еси/ и смирением Вышнее сокровище получил еси,/ преблаженне Максиме,// моли, молимся, о душах наши."},
  {"id": "cu-mol-0273", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0274", "section": "service", "who": "rubric", "text": "Марку, архиеп. Ефесскому,"},
  {"id": "cu-mol-0275", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0276", "section": "service", "who": "reader", "text": "Православия наставниче, новшеств противоборниче,/ степень веры, Церкве светильниче,/ учителей Богодухновенная печате, Марко всемудре,/ писании твоими вся просветил еси, цевнице духовная,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0277", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0278", "section": "service", "who": "rubric", "text": "Мартину Исповеднику, папе Римскому,"},
  {"id": "cu-mol-0279", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0280", "section": "service", "who": "reader", "text": "Истинных повелений устне распространил еси,/ учении Божественными вся просветил еси,/ зловерие низложил еси, Богомудре Мартине,/ святителю всечестне,/ поминай нас, угодниче Христов,/ еже к Нему ходатайствы твоими,// да в мире устроиши живот наш."},
  {"id": "cu-mol-0281", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0282", "section": "service", "who": "rubric", "text": "Мелетию, архиеп. Харьковскому,"},
  {"id": "cu-mol-0283", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0284", "section": "service", "who": "reader", "text": "Мира сего временная, яко преходящая уразумел еси,/ от юности постническое и многотрудное житие возлюбил еси, всеблаженне,/ иерархов славо и преподобных похвало,/ Предвечнаго Слова усердный благовестниче,/ сирых и неимущих крове и прибежище./ Тем же в молитвах пребывая, Христу утреневати прилежал еси/ и, Сего взыскуя, венец неувядаемый со всеми святыми стяжал еси,/ отче наш, святителю Мелетие,// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0285", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0286", "section": "service", "who": "rubric", "text": "Митрофану, еп. Воронежскому,"},
  {"id": "cu-mol-0287", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0288", "section": "service", "who": "reader", "text": "Правило веры и образ кротости,/ словом и житием, пастве твоей, отче смиренномудре Митрофане, был еси./ Темже и во светлостех святых,/ солнца светлейше возсиял еси,/ венцем нетления и славы украшаемь,/ моли Христа Бога,// стране нашей и граду твоему в мире спастися."},
  {"id": "cu-mol-0289", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0290", "section": "service", "who": "rubric", "text": "Михаилу, первому митр. Киевскому,"},
  {"id": "cu-mol-0291", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0292", "section": "service", "who": "reader", "text": "Днесь пророчествие во апостолех Первозваннаго исполнися:/ се бо на сих горах возсия благодать и вера умножися./ И иже неверием обветшавшии,/ Божественною купелию отродишася,/ и быша людие обновления,/ царское священие, язык свят, Христово стадо,/ емуже ты первый пастырь явился еси,/ яко первее Крещением послуживый./ И ныне, предстоя Владыце Христу Богу,/ моли, всем сыном русским спастися:// имаши бо дерзновение, яко иерарх Божий, и священнослужитель."},
  {"id": "cu-mol-0293", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0294", "section": "service", "who": "rubric", "text": "Модесту, архиеп. Иерусалимскому,"},
  {"id": "cu-mol-0295", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0296", "section": "service", "who": "reader", "text": "Преподобно пожив, Богомудре Модесте,/ и святительскою одеждою украшен,/ пастырю Иерусалима блаженнейший,/ в веселии ныне Христу предстоиши/ и концы озаряеши чудесы,/ помощник убо буди тя призывающим,// моляся, отче, о всех нас."},
  {"id": "cu-mol-0297", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0298", "section": "service", "who": "rubric", "text": "Моисею, архиеп. Новгородскому,"},
  {"id": "cu-mol-0299", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0300", "section": "service", "who": "reader", "text": "Чистоты ради жития твоего,/ пощения же и молитв и трудов/ сосуд благопотребен был еси Владыце Христу,/ Иже дарова тя стаду твоему,/ яко сокровище неотъемлемо, чудесы всех обогащающа./ Тем и мы, сошедшеся в память твою,/ верою и любовию вопием:// моли о нас, пречестный архиерею Моисее, отче наш."},
  {"id": "cu-mol-0301", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0302", "section": "service", "who": "rubric", "text": "Нектарию Эгинскому, митр. Пентапольскому,"},
  {"id": "cu-mol-0303", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0304", "section": "service", "who": "reader", "text": "Преподобнически пожив, яко мудрый иерарх,/ прославил еси Господа/ добродетельным житием, Нектарие преподобне./ Темже, Утешителя прославлен силою,/ Божественными мощми твоими,/ демоны отгониши и болящия исцеляеши,// верою приходящия ти."},
  {"id": "cu-mol-0305", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0306", "section": "service", "who": "rubric", "text": "Никите, Затворнику Печерскому, еп. Новгородскому,"},
  {"id": "cu-mol-0307", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0308", "section": "service", "who": "reader", "text": "Насладився, Богомудре, воздержания/ и желание плоти твоея обуздав,/ на престоле святительства сел еси,/ и яко звезда многосветлая, просвещая верных сердца/ зарями чудес твоих,/ отче наш, святителю Никито,/ и ныне моли Христа Бога,// да спасет души наша."},
  {"id": "cu-mol-0309", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0310", "section": "service", "who": "rubric", "text": "Николаю, архиеп. Мир Ликийских, чудотворцу,"},
  {"id": "cu-mol-0311", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0312", "section": "service", "who": "reader", "text": "Правило веры и образ кротости,/ воздержания учителя/ яви тя стаду твоему/ Яже вещей Истина./ Сего ради стяжал еси смирением высокая,/ нищетою богатая,/ отче священноначальниче Николае,/ моли Христа Бога,// спастися душам нашим."},
  {"id": "cu-mol-0313", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "cu-mol-0314", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0315", "section": "service", "who": "reader", "text": "Приспе день светлаго торжества,/ град Барский радуется,/ и с ним вселенная вся ликовствует/ песньми и пеньми духовными:/ днесь бо священное торжество/ в пренесение честных и многоцелебных мощей/ святителя и чудотворца Николая,/ якоже солнце незаходимое, возсия, светозарными лучами,/ разгоняя тьму искушений же и бед/ от вопиющих верно:// спасай нас яко предстатель наш великий, Николае."},
  {"id": "cu-mol-0316", "section": "service", "who": "rubric", "text": "Ин тропарь, на рождество,"},
  {"id": "cu-mol-0317", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0318", "section": "service", "who": "reader", "text": "Чудное и славное рождество твое, святителю Николае,/ Церковь днесь православных светло празднует,/ ибо стоянием ногу твоею/ яви тя Господь и провозвести быти светильника и учителя миряном,/ весь мир обогащающа и просвещающа чудесы./ Тем вопием ти:// моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0319", "section": "service", "who": "rubric", "text": "Ин тропарь, пред иконой «Зарайская»,"},
  {"id": "cu-mol-0320", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0321", "section": "service", "who": "reader", "text": "Пресветлый храме Святаго Духа,/ Богомудре отче Николае,/ благодатию Небес освяти души наша,/ заступи и покрый всечестным твоим омофором,/ его же приял еси от рук Пречистыя Девы,/ и просвети нас светом заповедей Христа,/ от Него бо приял еси глаголы жизни./ Моли благость Отца Небеснаго,/ во еже спастися/ православно чтущим тя,// даруя нам велию милость."},
  {"id": "cu-mol-0322", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение Великорецкой иконы из Вятки в Москву,"},
  {"id": "cu-mol-0323", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0324", "section": "service", "who": "reader", "text": "Яко драгоценное богатство,/ прииде к нам от Великия реки Вятки/ в царствующий сей град наш Москву/ честная икона образа твоего, святителю Николае,/ и многая убо чудеса в пришествии своем сотвори,/ болящия исцели и вся человеки удиви./ Сего ради повелением самодержца царя/ списася с нея сия честная икона твоя/ на просвещение и моление всем людем царска града,/ юже днесь зрим и покланяемся ей,/ моляще тя, таинника Христова:/ моли, святе, о всех нас,// даровати нам мир и велию милость."},
  {"id": "cu-mol-0325", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0326", "section": "service", "who": "rubric", "text": "Нифонту, патриарху Константинопольскому,"},
  {"id": "cu-mol-0327", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0328", "section": "service", "who": "reader", "text": "Делы просиял еси благочестия,/ высокотворным смирением украшаемь,/ Афона похвало, патриархов удобрение,/ Нифонте славне,// молися о нас, любовию славящих тя."},
  {"id": "cu-mol-0329", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0330", "section": "service", "who": "rubric", "text": "Нифонту, еп. Новгородскому,"},
  {"id": "cu-mol-0331", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0332", "section": "service", "who": "reader", "text": "Яко сый нравом православных/ Восточныя Церкве преданий истинный защитник,/ сподобился еси великаго во отцех Феодосия/ видети по смерти, яко жива,/ возвещающа тебе Царствия Небеснаго наследие,/ егоже неизреченных доброт/ ныне с ним неразлучно наслаждаяся,// моли и о нас, чадех своих, Нифонте прехвальне."},
  {"id": "cu-mol-0333", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0334", "section": "service", "who": "rubric", "text": "Павлу, патр. Константинопольскому, исп.,"},
  {"id": "cu-mol-0335", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0336", "section": "service", "who": "reader", "text": "Божественныя веры исповеданием/ другаго Павла тя Церковь, ревнителя во священницех, показа,/ свозопиет ти и Авель ко Господу,/ и Захариина кровь праведная./ Отче преподобне, Христа Бога моли// дароватися нам велией милости."},
  {"id": "cu-mol-0337", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0338", "section": "service", "who": "rubric", "text": "Павлу, митр. Тобольскому,"},
  {"id": "cu-mol-0339", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0340", "section": "service", "who": "reader", "text": "Прославим, вернии, благочестие возлюбившаго,/ и от юности иго Христово усердно восприимшаго,/ ревностнаго святителя Церкве Российския,/ в Богоспасаемом граде Тобольске подвизавшагося./ Ты же, Богомудре отче Павле,/ телом убо в нетлении почивая,/ духом же Престолу Божию предстоя,// моли спастися всем нам."},
  {"id": "cu-mol-0341", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0342", "section": "service", "who": "rubric", "text": "Петру, митр. Московскому, всея России чудотворцу,"},
  {"id": "cu-mol-0343", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0344", "section": "service", "who": "reader", "text": "Яже прежде безплодная земле,/ ныне веселися:/ се бо Христос светильника в тебе показа,/ яве сияюща в мире,/ и исцелевающа недуги и болезни наша./ Сего ради ликуй и веселися со дерзновениием:// святитель бо есть Вышняго сия соделоваяй."},
  {"id": "cu-mol-0345", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "cu-mol-0346", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0347", "section": "service", "who": "reader", "text": "Наста днесь всечестный праздник/ пренесения честных мощей твоих, святителю Петре,/ веселя изрядно твое стадо,/ и верное отечество, и люди,/ о нихже не оскудевай, моляся Христу Богу,/еже от Него дарованней ти пастве сохранитися от враг ненаветованней// и спастися душам нашим."},
  {"id": "cu-mol-0348", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0349", "section": "service", "who": "rubric", "text": "Питириму, еп. Великопермскому,"},
  {"id": "cu-mol-0350", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0351", "section": "service", "who": "reader", "text": "Православия наставниче,/ благочестия учителю и милости сокровище,/ архиереев украшение,/ людей зырянских наставниче,/ святителю Питириме,/ душу свою за Христа положивый,/ моли Единаго Человеколюбца о пастве твоей и о всех// любовию чтущих память твою."},
  {"id": "cu-mol-0352", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0353", "section": "service", "who": "rubric", "text": "Питириму, еп. Тамбовскому,"},
  {"id": "cu-mol-0354", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0355", "section": "service", "who": "reader", "text": "Веры и благочестия наставниче,/ Церкве светильниче, монашествующих образе,/ святителю Питириме премудре,/ стадо твое благочестно упасл еси/ и ко Христу привел еси,/ темже в Вышних венцем славы украшен,/ с нами на земли духом пребываеши, сияя чудесы./ Моли Христа Бога,// спастися душам нашим."},
  {"id": "cu-mol-0356", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0357", "section": "service", "who": "rubric", "text": "Порфирию, архиеп. Газскому,"},
  {"id": "cu-mol-0358", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0359", "section": "service", "who": "reader", "text": "Труды и болезни твоя, яже по благочестию,/ кто исповесть, отче?/ день бо и ночь не престал еси трудяся,/ дондеже от нечестия Газу очистив, благочестие насадил еси,/ тем яко всегда еси предстатель о стаде твоем,/ тако, святе Порфирие,// моли Христа Бога да спасет души наша."},
  {"id": "cu-mol-0360", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0361", "section": "service", "who": "rubric", "text": "Проклу, архиеп. Константинопольскому,"},
  {"id": "cu-mol-0362", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0363", "section": "service", "who": "reader", "text": "Иже Божественным началом премудрости,/ страхом Господним утверждся,/ оттуду священными восхождении возшел еси/ во ученичество Златоуста,/ и архиерейскаго того престола достоин быв чистоты добротами,/ апостольским правилом себе вообразив,/ не себе живый, но Христу и стаду твоему./ Тем в нетленный живот апостольски вселился еси,/ иерарше Прокле,/ моли Христа Бога// спастися душам нашим."},
  {"id": "cu-mol-0364", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0365", "section": "service", "who": "rubric", "text": "Савве I, архиеп. Сербскому,"},
  {"id": "cu-mol-0366", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0367", "section": "service", "who": "reader", "text": "Пути вводящаго в жизнь,/ наставник, и первопрестольник, и учитель был еси:/ первее бо пришед, святителю Савво,/ отечество твое просветил еси,/ и, породив тое Духом Святым;/ яко древа маслинная/ в мысленнем раи насадил еси всеосвященная твоя чада./ Тем яко апостолом и святителем сопрестольна/ чтуще тя молим:/ моли Христа Бога// даровати нам велию милость."},
  {"id": "cu-mol-0368", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0369", "section": "service", "who": "rubric", "text": "Савве II, архиеп. Сербскому,"},
  {"id": "cu-mol-0370", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0371", "section": "service", "who": "reader", "text": "Исправление веры и образ кротости,/ и якоже сад посреде рая,/ преподобными делы твоими мир просвещаеши,/ сего ради к честней раце мощей твоих любовию прикасаемся,/ лобызаем их и верно вопием:/ предстани в помощь воспевающим память святую твою и светоносную,/ святителю отче Савво пребогате, молимся,/ Христу Богу молися// спастися душам нашим."},
  {"id": "cu-mol-0372", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0373", "section": "service", "who": "rubric", "text": "Святителям Московским: Петру, Алексию, Ионе, Филиппу и Ермогену,"},
  {"id": "cu-mol-0374", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0375", "section": "service", "who": "reader", "text": "Первопрестольницы Российстии,/ истиннии хранителие апостольских преданий,/ столпи непоколебимии, православия наставницы,/ Петре, Алексие, Ионо, Филиппе и Ермогене,/ Владыку всех молите/ мир вселенней даровати,// и душам нашим велию милость."},
  {"id": "cu-mol-0376", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0377", "section": "service", "who": "rubric", "text": "Серапиону, архиеп. Новгородскому,"},
  {"id": "cu-mol-0378", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0379", "section": "service", "who": "reader", "text": "Твердый адамант воистинну, отче, показался еси,/ во всем подобяся Владыце своему и Господу,/ неправедная изгнания, радуяся, претерпел еси,/ темже и Христос святителем и мучеником сликовна тя сотвори/ и дарова тя стаду твоему, яко сокровище неотъемлемо,/ чудесы всех обогащающее,/ яко да и мы, сошедшеся к раце мощей твоих,/ любовию вопием ти:/ о великий во святителех и дивный во страдальцех/ пречестный архиерею, Серапионе отче наш,/ моли о нас всеблагаго Бога,// да спасет души наша."},
  {"id": "cu-mol-0380", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0381", "section": "service", "who": "rubric", "text": "Симону, еп. Владимирскому и Суздальскому,"},
  {"id": "cu-mol-0382", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0383", "section": "service", "who": "reader", "text": "Житий преподобных отец Печерских списателю известный,/ святителю Христов Симоне всеблаженне,/ молися прилежно с ними Христу Богу,/ да управит в мире живот наш/ и в книги животныя да напишет ны,// спасая души наша."},
  {"id": "cu-mol-0384", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0385", "section": "service", "who": "rubric", "text": "Собору Вселенских учителей и святителей Василию Великому, Григорию Богослову и Иоанну Златоустому,"},
  {"id": "cu-mol-0386", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0387", "section": "service", "who": "reader", "text": "Яко апостолов единонравнии/ и вселенныя учителие,/ Владыку всех молите/ мир вселенней даровати// и душам нашим велию милость."},
  {"id": "cu-mol-0388", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0389", "section": "service", "who": "rubric", "text": "Софронию, еп. Врачанскому (Болг.),"},
  {"id": "cu-mol-0390", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0391", "section": "service", "who": "reader", "text": "Щитом веры вооружився,/ мечем словесе безбожныя агаряны посекая,/ стадо твое упасл еси на земли./ В Небесней же обители вселився,/ Христа моли даровати народу нашему// мир и велию милость."},
  {"id": "cu-mol-0392", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0393", "section": "service", "who": "rubric", "text": "Софронию, еп. Иркутскому,"},
  {"id": "cu-mol-0394", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0395", "section": "service", "who": "reader", "text": "От юности Христа возлюбил еси, блаженне Софроние,/ добре управил еси иноческия обители/ и, архиерейства саном почтен быв,/ упасл еси Иркутскую паству,/ темже и по преставлении дарования чудес от Бога приял еси,/ и молиши Христа Бога// избавити нас от бед и спасти души наша."},
  {"id": "cu-mol-0396", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0397", "section": "service", "who": "rubric", "text": "Спиридону, еп. Тримифунтскому, чудотворцу,"},
  {"id": "cu-mol-0398", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0399", "section": "service", "who": "reader", "text": "Собора Перваго показался еси поборник и чудотворец,/ Богоносе Спиридоне, отче наш./ Темже мертву ты во гробе возгласив,/ и змию в злато претворил еси,/ и внегда пети тебе святыя молитвы,/ Ангелы сослужащия тебе имел еси, священнейший./ Слава Давшему тебе крепость,/ слава Венчавшему тя,// слава Действующему тобою всем исцеления."},
  {"id": "cu-mol-0400", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0401", "section": "service", "who": "rubric", "text": "Стефану, еп. Великопермскому,"},
  {"id": "cu-mol-0402", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0403", "section": "service", "who": "reader", "text": "Божественным желанием/ от юнаго возраста, Стефане премудре, разжегся,/ ярем Христов взял еси/ и людей оляденевшая древле неверием сердца,/ Божественное семя в них сеяв,/ евангельски духовне породил еси./ Темже преславную твою память почитающе, молим тя:/ моли, Егоже проповедал еси,// да спасет души наша."},
  {"id": "cu-mol-0404", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0405", "section": "service", "who": "rubric", "text": "Стефану Исповеднику, архиеп. Сурожскому,"},
  {"id": "cu-mol-0406", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0407", "section": "service", "who": "reader", "text": "Яко святитель со Безплотными единожитель быв,/ священномучениче Стефане,/ восприем бо Крест яко оружие,/ и став крепко сопротив иконоукорителя и духоборцев,/ не покланяющихся пречистому образу Христа Бога нашего,/ и отсекл еси всяку ересь лукавых./ Того ради прием мучения венец,/ избавил еси град твой Сурож от всякия неприязни./ И ныне молим тя, святе,/ да избавиши нас от всяких злых искушений, и бед,// и вечныя муки."},
  {"id": "cu-mol-0408", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0409", "section": "service", "who": "rubric", "text": "Тихону, еп. Амафунтскому,"},
  {"id": "cu-mol-0410", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0411", "section": "service", "who": "reader", "text": "Пустынный житель и в телеси ангел,/ и чудотворец явился еси, Богоносе отче наш Тихоне:/ постом, бдением, молитвою Небесная дарования приим,/ исцеляеши недужныя и души верою притекающих ти./ Слава Давшему тебе крепость,/ слава Венчавшему тя,// слава Действующему тобою всем исцеления."},
  {"id": "cu-mol-0412", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0413", "section": "service", "who": "rubric", "text": "Тихону, еп. Воронежскому, Задонскому чудотворцу,"},
  {"id": "cu-mol-0414", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0415", "section": "service", "who": "reader", "text": "Православия наставниче, благочестия учителю,/ покаяния проповедниче, Златоустаго ревнителю,/ пастырю предобрый,/ новый России светильниче и чудотворче,/ паству твою добре упасл еси/ и писаньми твоими вся ны наставил еси,/ темже венцем нетления/ украшен от Пастыреначальника,// моли Его спастися душам нашим."},
  {"id": "cu-mol-0416", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0417", "section": "service", "who": "rubric", "text": "Тихону, патриарху Московскому и всея Руси,"},
  {"id": "cu-mol-0418", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0419", "section": "service", "who": "reader", "text": "В годину тяжкую Богом избранный/ в совершенной святости и любви Бога прославил еси,/ во смирении величие, в простоте и кротости силу Божию являя,/ положил душу за Церковь, за люди своя,/ исповедниче патриарше святе Тихоне,/ моли Христа Бога,/ Емуже сораспялся еси,// и ныне спасти землю Русскую и паству Твою."},
  {"id": "cu-mol-0420", "section": "service", "who": "rubric", "text": "Ин тропарь, на прославление,"},
  {"id": "cu-mol-0421", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "cu-mol-0422", "section": "service", "who": "reader", "text": "Апостольских преданий ревнителя/ и Христовой Церкви пастыря добраго,/ душу свою за овцы положившаго,/ жребием Божиим избраннаго,/ Всероссийскаго патриарха Тихона восхвалим/ и к нему с верою и упованием возопиим:/ предстательством святительским ко Господу/ Церковь Русскую в тишине соблюди,/ расточенныя чада ея во едино стадо собери,/ отступившия от правыя веры к покаянию обрати,/ страну нашу от междоусобныя брани сохрани,// и мир Божий людям испроси."},
  {"id": "cu-mol-0423", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0424", "section": "service", "who": "rubric", "text": "Феодору, еп. Едесскому,"},
  {"id": "cu-mol-0425", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0426", "section": "service", "who": "reader", "text": "Неволею паству святительскую приим,/ но волею подвигнувся о Божии Церкви,/ и перстию Христова гроба невернаго Моавия царя уверив,/ и с телесною слепотою вкупе и душевную ему исцелив, благоверна показа,/ с нимже и еретики от Божия Церкве, яко волки, отгнав,/ честный святителю Феодоре,// моли спастися душам нашим."},
  {"id": "cu-mol-0427", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0428", "section": "service", "who": "rubric", "text": "Феодору, архиеп. Ростовскому,"},
  {"id": "cu-mol-0429", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0430", "section": "service", "who": "reader", "text": "От юности, премудре, прилежно подвизався,/ и извещением Святаго Духа/ превеликую обитель воздвиже Пресвятей Богородице/ в похвалу Рождества Ея,/ струями же слез твоих безплотныя враги погрузил еси,/ и, жития твоего целомудрием со Ангельскими лики совокупився,/ преподобне отче Феодоре,/ с ними же Христа Бога моли// спастися душам нашим."},
  {"id": "cu-mol-0431", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0432", "section": "service", "who": "rubric", "text": "Феодору, еп. Суздальскому,"},
  {"id": "cu-mol-0433", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0434", "section": "service", "who": "reader", "text": "В молитвах бдя, сердцем же о стаде твоем выну болезнуя,/ учением своим всех просветил еси, Феодоре премудре,/ темже Христа Бога моли,// в день памяти твоея даровати нам велию милость."},
  {"id": "cu-mol-0435", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0436", "section": "service", "who": "rubric", "text": "Феодосию, архиеп. Черниговскому,"},
  {"id": "cu-mol-0437", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0438", "section": "service", "who": "reader", "text": "Преудобрен во архиереех, святителю Феодосие,/ был еси светило своему стаду,/ таже преставился еси в вечныя обители,/ умоли у Престола Царя Славы избавитися нам от находящих на ны зол,// и спастися душам нашим, святе, молитвами твоими."},
  {"id": "cu-mol-0439", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0440", "section": "service", "who": "rubric", "text": "Феоктисту, архиеп. Новгородскому,"},
  {"id": "cu-mol-0441", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0442", "section": "service", "who": "reader", "text": "Божия Слова Премудрости изрядный служитель,/ Ангельскаго жительства истинный подражатель,/ Божественныя чистоты рачитель,/ архиереом сопрестольниче, преподобным сожительниче,/ пастырская красота,/ Великому Новуграду похвала,/ святителю пречестный Феоктисте, отче наш,/ Емуже, Слову Божию, в житии сем послужил еси,// моли спастися душам нашим."},
  {"id": "cu-mol-0443", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0444", "section": "service", "who": "rubric", "text": "Феофану, Затворнику Вышенскому, еп.,"},
  {"id": "cu-mol-0445", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "cu-mol-0446", "section": "service", "who": "reader", "text": "Православия наставниче,/ благочестия учителю и чистоты,/ Вышенский подвижниче святителю Феофане Богомудре,/ писаньми твоими слово Божие изъяснил еси/ и всем верным путь ко спасению указал еси.// Моли Христа Бога спастися душам нашим."},
  {"id": "cu-mol-0447", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0448", "section": "service", "who": "rubric", "text": "Филарету, митр. Московскому,"},
  {"id": "cu-mol-0449", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0450", "section": "service", "who": "reader", "text": "Духа Святаго благодать стяжав,/ богомудре святителю Филарете,/ истину и правду разумом просвещенным/ людем проповедал еси,/ мир и милость сердцем умиленным/ страждущим явил еси,/ яко учитель веры и страж неусыпный/ паству российскую жезлом правости сохранил еси./ Сего ради ко Христу Богу дерзновение имея,/ моли даровати Церкве утверждение,// и душам нашим спасение."},
  {"id": "cu-mol-0451", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0452", "section": "service", "who": "rubric", "text": "Филиппу II, митр. Московскому,"},
  {"id": "cu-mol-0453", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "cu-mol-0454", "section": "service", "who": "reader", "text": "Чудо явися, извещением и делы возсияв,/ Духа Святаго произбранием святительства паству приим,/ откровением Божиим церковь разобра/ и величайшую воздвиже,/ всечестне Филиппе, святителю великий,/ мир граду даруй нашему Москве// и велию милость."},
  {"id": "cu-mol-0455", "section": "service", "who": "rubric", "text": "Ин тропарь, глас 8"},
  {"id": "cu-mol-0456", "section": "service", "who": "reader", "text": "Первопрестольников преемниче,/ столпе Православия, истины поборниче,/ новый исповедниче, святителю Филиппе,/ положивый душу за паству твою,/ темже яко имея дерзновение ко Христу,/ моли за град же и люди,// чтущия достойно святую память твою."},
  {"id": "cu-mol-0457", "section": "service", "who": "rubric", "text": "Ин тропарь, на перенесение мощей,"},
  {"id": "cu-mol-0458", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "cu-mol-0459", "section": "service", "who": "reader", "text": "Радостный возсия день светлаго торжества:/ днесь церковная расширяются недра,/ приемлюще духовных даров неоскудеемо боготворное сокровище,/ струю благодатей неисчерпаемую,/ источника чудесем обильна,/ чудотворивыя и священныя мощи твоя,/ святителю Филиппе./ Темже моли прославившаго тя Дародателя Христа Бога/ о воспевающих тя// и кланяющихся священным мощем твоим."},
  {"id": "cu-mol-0460", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "cu-mol-0461", "section": "service", "who": "rubric", "text": "Фотию, митр. Киевскому и всея Руси,"},
  {"id": "cu-mol-0462", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "cu-mol-0463", "section": "service", "who": "reader", "text": "Словес евангельских послушателю/ и Божественных учений рачителю,/ премудрый наказателю,/ всегда страху Господню поучаяйся,/ в молитвах к Богу простираяйся,/ заградителю уст кривоглаголющим слово правыя веры,/ апостолом сопричастниче,/ вере Христовой утвердителю,/ пророчески вещателю, святителю Фотие,/ моли Христа Бога// умирити мир и спасти души наша."},
];

